//! The fixed `.ws` text that `ws up` writes when a project has no setup file (002).

/// The default `.ws` document, byte-identical to "Default Content (Normative)" in
/// `specs/002-default/spec.md`.
///
/// It is the only source for the created file, the in-memory fallback, and an empty document. The
/// comment lines are part of the contract, so the text is kept verbatim rather than serialized from
/// a typed value.
pub const DEFAULT_CONTENT: &str = "\
# Generated by ws because this folder had no .ws file.
# Edit freely; run `ws help config` for the full language reference.
version: 1
windows:
  - name: root
    path: .
  - name: file
    path: .
    command: yazi
  - name: git
    path: .
    command: lazygit
  - name: claude
    path: .
    command: claude
";

#[cfg(test)]
mod tests {
    use tempfile::tempdir;

    use super::DEFAULT_CONTENT;
    use crate::config::{parse, validator};

    #[test]
    fn given_the_default_content_when_inspected_then_it_ends_with_a_newline() {
        assert!(DEFAULT_CONTENT.ends_with('\n'));
    }

    #[test]
    fn given_the_default_content_when_loaded_then_it_gives_the_four_default_windows_in_order() {
        let project = tempdir().expect("a temporary project folder should be available");
        let source_path = project.path().join(".ws");

        let definition = parse(DEFAULT_CONTENT, &source_path)
            .and_then(|definition| validator::validate(definition, &source_path))
            .expect("the default content should pass the normal loader");

        let windows: Vec<_> = definition
            .windows
            .iter()
            .map(|window| (window.name.as_str(), window.command.as_deref()))
            .collect();
        assert_eq!(
            windows,
            [
                ("root", None),
                ("file", Some("yazi")),
                ("git", Some("lazygit")),
                ("claude", Some("claude")),
            ]
        );
    }

    #[test]
    fn given_the_default_content_when_loaded_then_every_window_starts_in_the_project_folder() {
        let project = tempdir().expect("a temporary project folder should be available");
        let source_path = project.path().join(".ws");
        let canonical_project = project.path().canonicalize().unwrap();

        let definition = parse(DEFAULT_CONTENT, &source_path)
            .and_then(|definition| validator::validate(definition, &source_path))
            .expect("the default content should pass the normal loader");

        assert!(
            definition
                .windows
                .iter()
                .all(|window| window.path == canonical_project),
            "{:?}",
            definition.windows
        );
    }
}
